class Commando < Formula
  desc "Colorful TUI that turns a command's man page into a form for its options"
  homepage "https://github.com/lonedevel/commando"
  license "Apache-2.0"

  head do
    url "https://github.com/lonedevel/commando.git", branch: "main"
    depends_on "go" => :build
  end

  # Generated by scripts/update-formula.sh from the release's checksums.txt.
  on_macos do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.21.0/commando_0.21.0_darwin_arm64.tar.gz"
      sha256 "6ca74ff85e98baf29635771f09d33848760614f95956e2ae6f000c5147190395"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.21.0/commando_0.21.0_darwin_amd64.tar.gz"
      sha256 "1d0438d145471ecccebb9d8591529222b634c88d7af9c15dc4ab843d1f44f7c5"
    end
  end

  on_linux do
    on_arm do
      url "https://github.com/lonedevel/commando/releases/download/v0.21.0/commando_0.21.0_linux_arm64.tar.gz"
      sha256 "67b8ba6170d852be44710a518a8740617a7d33e1178e2a193878b0346c713024"
    end
    on_intel do
      url "https://github.com/lonedevel/commando/releases/download/v0.21.0/commando_0.21.0_linux_amd64.tar.gz"
      sha256 "456438566c8078f564a418b685f6acc32b46ca8b38c92151fa2977ea5339f2bd"
    end
  end

  def install
    if build.head?
      system "go", "build", *std_go_args(ldflags: "-s -w -X main.version=#{version}"), "./cmd/commando"
      man1.install "docs/commando.1"
    else
      bin.install "commando"
      man1.install "commando.1"
    end
    generate_completions_from_executable(bin/"commando", "--completion")
  end

  def caveats
    <<~EOS
      To edit the command you're typing with Ctrl-X Ctrl-O, add to your shell config:
        zsh:  eval "$(commando --init zsh)"
        bash: eval "$(commando --init bash)"
        fish: commando --init fish | source
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/commando --version")
    assert_match "bindkey", shell_output("#{bin}/commando --init zsh")
    assert_match "compdef", shell_output("#{bin}/commando --completion zsh")
    assert_path_exists man1/"commando.1"

    # Parse a manual without needing a terminal.
    ENV["COMMANDO_CACHE_DIR"] = testpath/"cache"
    output = shell_output("#{bin}/commando --dump --no-cache ls")
    assert_match "\"names\"", output
  end
end
